#include <stdio.h>

int mySqrt(int x) {
    if (x < 2) return x;

    int left = 1;
    int right = x / 2;
    int answer = 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (mid <= x / mid) {
            answer = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return answer;
}

